import numpy as np
import time
import math
from scipy.fft import rfft, irfft, next_fast_len
from scipy.optimize import linprog


def _get_parent():
    try:
        h = globals()["height_sequence_1"]
        p = np.asarray(h, dtype=np.float64).ravel()
    except Exception:
        p = np.ones(198, dtype=np.float64)
    if p.size == 0:
        p = np.ones(198, dtype=np.float64)
    p = np.clip(p, 0.0, 1000.0)
    p = np.where(np.isfinite(p), p, 0.0)
    if p.size == 0:
        p = np.ones(198, dtype=np.float64)
    return p


def _conv_full(a):
    n = len(a)
    if n <= 512:
        return np.convolve(a, a, mode="full")
    fsize = next_fast_len(2 * n - 1)
    F = rfft(a, fsize)
    c = irfft(F * F, fsize)[: 2 * n - 1]
    np.maximum(c, 0.0, out=c)
    return c


def _score(a):
    n = len(a)
    s = float(a.sum())
    if s < 0.01:
        return math.inf
    b = _conv_full(a)
    m = float(b.max())
    if not math.isfinite(m) or m < 0:
        return math.inf
    return 2.0 * n * m / (s * s)


def _build_A(f, n):
    A = np.zeros((2 * n - 1, n))
    for j in range(n):
        A[j : j + n, j] = f
    return A


def _lp_direction(f, n):
    b = _conv_full(f)
    M = float(b.max())
    if M < 1e-15:
        return None, M
    A = _build_A(f, n)
    c = -np.ones(n)
    b_ub = np.full(2 * n - 1, M)
    try:
        res = linprog(
            c, A_ub=A, b_ub=b_ub,
            bounds=[(0, None)] * n,
            method="highs",
            options={"presolve": True},
        )
    except Exception:
        return None, M
    if res.status != 0 or res.x is None:
        return None, M
    g = np.asarray(res.x, dtype=np.float64)
    g_sum = float(g.sum())
    if g_sum < 1e-15:
        return None, M
    return g / g_sum, M


def _lp_optimize(f0, n, stop_time, seed):
    rng = np.random.default_rng(seed)
    f = np.clip(np.asarray(f0, dtype=np.float64).ravel()[:n].copy(), 0, None)
    while f.size < n:
        f = np.concatenate([f, np.zeros(n - f.size)])
    f = f[:n]
    f_sum = float(f.sum())
    if f_sum < 1e-10:
        f = np.ones(n) / n
    else:
        f = f / f_sum

    best_f = f.copy()
    best_score = _score(f)
    t = 0.25
    t_min = 0.015
    t_max = 0.55
    stall = 0
    max_stall = 200
    iteration = 0

    while time.monotonic() < stop_time - 2.0:
        if iteration % 32 == 0 and time.monotonic() > stop_time - 2.0:
            break

        g_dir, M = _lp_direction(f, n)
        if g_dir is None:
            stall += 8
            if stall > max_stall:
                break
            f = np.clip(f + rng.normal(0, 0.03, n), 0, None)
            fs = f.sum()
            if fs > 1e-10:
                f = f / fs
            else:
                f = best_f.copy()
            continue

        dist = float(np.linalg.norm(g_dir - f))
        if dist < 1e-7:
            stall += 3
            if stall > max_stall:
                break
            f = np.clip(f + rng.normal(0, 0.06, n), 0, None)
            fs = f.sum()
            if fs > 1e-10:
                f = f / fs
            else:
                f = best_f.copy()
            continue

        improved = False
        for _ in range(10):
            f_new = (1.0 - t) * f + t * g_dir
            f_new = np.clip(f_new, 0, None)
            fs_new = float(f_new.sum())
            if fs_new < 1e-10:
                t = max(t_min, t * 0.5)
                continue
            sc = _score(f_new)
            if sc < best_score - 1e-12:
                f = f_new
                best_f = f.copy()
                best_score = sc
                improved = True
                t = min(t_max, t * 1.04)
                stall = 0
                break
            else:
                t = max(t_min, t * 0.55)

        if not improved:
            stall += 1
            if stall >= max_stall:
                f = np.clip(f + rng.normal(0, 0.08, n), 0, None)
                fs = f.sum()
                if fs > 1e-10:
                    f = f / fs
                else:
                    f = best_f.copy()
                t = 0.25
                stall = 0
        iteration += 1

    return best_f, best_score


def _polish(a, stop_time):
    n = len(a)
    best = np.clip(np.asarray(a, dtype=np.float64).ravel(), 0, None).copy()
    fs = best.sum()
    if fs < 1e-10:
        return best, _score(best)
    best = best / fs
    best_sc = _score(best)
    rng = np.random.default_rng(4242)
    no_imp = 0

    while time.monotonic() < stop_time - 2.0:
        improved = False
        order = rng.permutation(n)
        for i in order:
            if time.monotonic() > stop_time - 2.0:
                break
            orig = best[i]
            multipliers = (0.3, 0.5, 0.75, 1.25, 1.6, 2.2, 0.0)
            best_val = orig
            best_val_sc = best_sc
            for mlt in multipliers:
                best[i] = orig * mlt if orig > 1e-12 else (0.05 if mlt > 0 else 0.0)
                if best.sum() < 0.01:
                    best[i] = orig
                    continue
                sc = _score(best)
                if sc < best_val_sc - 1e-13:
                    best_val = best[i]
                    best_val_sc = sc
            best[i] = best_val
            if best_val_sc < best_sc - 1e-13:
                best_sc = best_val_sc
                improved = True

        # 2-coordinate moves
        for _ in range(60):
            if time.monotonic() > stop_time - 2.0:
                break
            i, j = int(rng.integers(n)), int(rng.integers(n))
            if i == j:
                continue
            oi, oj = best[i], best[j]
            for mi in (0.5, 1.5):
                for mj in (0.5, 1.5):
                    best[i] = oi * mi if oi > 1e-12 else 0.05
                    best[j] = oj * mj if oj > 1e-12 else 0.05
                    if best.sum() < 0.01:
                        best[i], best[j] = oi, oj
                        continue
                    sc = _score(best)
                    if sc < best_sc - 1e-13:
                        best_sc = sc
                        improved = True
            best[i], best[j] = oi, oj

        if not improved:
            no_imp += 1
            if no_imp >= 6:
                break
        else:
            no_imp = 0

    return best, best_sc


def propose_candidate(seed=42, budget_s=1300, **kwargs):
    t0 = time.monotonic()
    budget = max(10.0, float(budget_s))
    deadline = t0 + budget - 12.0

    parent = _get_parent()
    n_p = len(parent)

    # Fallback
    fallback = parent.copy()
    try:
        fallback_sc = _score(fallback)
    except Exception:
        fallback_sc = math.inf
    if not math.isfinite(fallback_sc):
        fallback = np.ones(32) / 32
        fallback_sc = _score(fallback)

    best_seq = fallback.copy()
    best_score = fallback_sc

    def _try(n, init_arr, stop, sd):
        nonlocal best_seq, best_score
        try:
            res, sc = _lp_optimize(init_arr, n, stop, sd)
        except Exception:
            return
        if not np.all(np.isfinite(res)):
            return
        res = np.clip(res, 0, 1000)
        if res.sum() < 0.01:
            return
        if sc < best_score:
            try:
                exact = float(evaluate_sequence([float(x) for x in res]))
            except Exception:
                exact = math.inf
            if math.isfinite(exact) and exact < best_score - 1e-13:
                best_seq = res.copy()
                best_score = exact

    # Phase 1: LP on parent length with several initializations
    n = n_p
    i_arr = np.arange(n, dtype=np.float64)
    rng_main = np.random.default_rng(seed)

    inits = []
    inits.append(parent.copy())
    # cosine bump
    inits.append(0.5 + 0.5 * np.cos(2 * math.pi * i_arr / n))
    # superposition
    sup = np.ones(n) * 0.3
    for fr in (1, 2, 3, 5):
        ph = rng_main.uniform(0, 2 * math.pi)
        sup += 0.35 * np.cos(2 * math.pi * fr * i_arr / n + ph)
    inits.append(np.abs(sup) + 0.05)
    # random
    inits.append(np.abs(rng_main.normal(0, 1, n)) + 0.1)
    # parent scaled + noise
    inits.append(np.abs(parent + rng_main.normal(0, 0.3 * max(1.0, np.mean(parent)), n)) + 0.01)

    # Allocate time: ~60% of budget to Phase 1
    phase1_end = t0 + budget * 0.55
    time_per_init = max(8.0, (phase1_end - t0) / len(inits))

    for idx, init in enumerate(inits):
        if time.monotonic() > phase1_end - 5.0:
            break
        if best_score < 1.50:
            break
        stop = min(phase1_end - 3.0, time.monotonic() + time_per_init)
        _try(n, init, stop, seed + 1000 * (idx + 1))

    # Phase 2: try other lengths
    phase2_end = t0 + budget * 0.80
    other_lengths = [128, 198, 256, 320, 384, 512]
    if n_p not in other_lengths:
        other_lengths.append(n_p)
    other_lengths = sorted(set(other_lengths))
    time_per_len = max(5.0, (phase2_end - phase1_end) / max(1, len(other_lengths)))

    for L in other_lengths:
        if time.monotonic() > phase2_end - 5.0:
            break
        if best_score < 1.50:
            break
        stop = min(phase2_end - 3.0, time.monotonic() + time_per_len)
        # Initialize from parent (interpolated) or best_seq
        if L == len(best_seq) and best_score < 2.0:
            init_l = best_seq.copy()
        else:
            init_l = np.interp(
                np.linspace(0, 1, L), np.linspace(0, 1, len(parent)), parent
            )
        _try(L, init_l, stop, seed + 50000 + L)

    # Phase 3: polish
    polish_end = deadline - 3.0
    if time.monotonic() < polish_end - 10.0:
        try:
            best_seq, best_score = _polish(best_seq, polish_end)
        except Exception:
            pass

    # Final validation
    try:
        final_sc = float(evaluate_sequence([float(x) for x in best_seq]))
    except Exception:
        final_sc = math.inf

    if not math.isfinite(final_sc):
        try:
            final_sc = float(evaluate_sequence([float(x) for x in fallback]))
        except Exception:
            final_sc = math.inf
        if not math.isfinite(final_sc):
            return [1.0]
        return [float(x) for x in fallback]

    if final_sc < best_score - 1e-12:
        best_score = final_sc

    return [float(x) for x in best_seq]
